// Loop over input items
const results = $input.all().map(item => {
  // Extract the "output" field
  const output = item.json.output;

  // Split the output into lines and extract key-value pairs
  const lines = output.split("\n");
  const data = {};
  lines.forEach(line => {
    const [key, value] = line.split(":").map(str => str.trim());
    data[key] = value;
  });

  // Return the structured data
  return {
    json: data
  };
});

return results;

